		            local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Linear, Enum.EasingDirection.Out)
		            currentTween = TweenService:Create(localCache.Root, tweenInfo, {CFrame = tPart.CFrame})
		            currentTween:Play()
